package ru.oopssre.imperialschool.viewstv;

import org.json.*;
import java.time.*;
import java.util.*;
import java.util.regex.Pattern;

/** Existing schema-3 ordinary collections and API-1.7 server weather. */
public final class Sources {
    static double score(int w,int h){return Math.abs(Math.log((double)w/h/(16.0/9.0)))*100+Math.abs(Math.log((double)w*h/(3840.0*2160)));}
    public static Protocol.Theme theme(JSONObject c,JSONObject catalogue)throws JSONException {
        String id=c.getString("id"),title=c.getString("title");Protocol.require(id.matches("[a-z0-9][a-z0-9_-]{0,79}")&&!title.isEmpty()&&title.length()<=300,"Неверная коллекция");
        if(c.optString("type").equals("weather")){JSONObject formats=c.getJSONObject("formats");String best=null;int w=0,h=0;double rank=Double.MAX_VALUE;for(Iterator<String> it=formats.keys();it.hasNext();){String key=it.next();JSONObject f=formats.getJSONObject(key);int fw=f.getInt("width"),fh=f.getInt("height");Protocol.require(Protocol.id(key)&&fw>0&&fh>0&&fw<=16384&&fh<=16384,"Неверный погодный формат");if(fw>=fh&&score(fw,fh)<rank){best=key;w=fw;h=fh;rank=score(fw,fh);}}Protocol.require(best!=null,"Нет горизонтального погодного формата");return new Protocol.Theme(id,title,best,c.getString("current_url"),w,h,c);}
        JSONArray items=catalogue.getJSONArray("items");JSONObject best=null;for(int i=0;i<items.length();i++){JSONObject row=items.getJSONObject(i);if(row.getString("collection").equals(id)){try{best=picture(row.getJSONArray("files"));break;}catch(IllegalArgumentException ignored){}}}Protocol.require(best!=null,"Нет горизонтальных изображений");return new Protocol.Theme(id,title,"plain","",best.getInt("width"),best.getInt("height"),c);
    }
    public static boolean pictureURL(String value,String collection){String rel=Protocol.url(value).getPath().substring("/assets/arcade/views/".length());return rel.matches("(?:collections/"+Pattern.quote(collection)+"/)?files/[a-zA-Z0-9_-]+\\.(?:jpe?g|png)");}
    static JSONObject picture(JSONArray files)throws JSONException {JSONObject best=null;double rank=Double.MAX_VALUE;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);try{ImageFormat.canonical(f.getString("format"));}catch(IllegalArgumentException|JSONException unsupported){continue;}int w=f.getInt("width"),h=f.getInt("height");if(w>=h&&w>0&&h>0&&w<=16384&&h<=16384&&score(w,h)<rank){best=f;rank=score(w,h);}}Protocol.require(best!=null,"Нет горизонтального изображения");return best;}
    static Protocol.Frame pictureFrame(JSONObject file,Protocol.Theme theme,String title,long at,long until)throws JSONException {String format=ImageFormat.canonical(file.getString("format"));String path=file.getString("url"),sha=file.getString("sha256");Protocol.require(ImageFormat.fromURL(path).equals(format),"Расширение изображения не совпало с форматом");long bytes=Protocol.integer(file,"bytes",1,Protocol.MAX_IMAGE);Protocol.require(pictureURL(path,theme.id)&&Protocol.hash(sha),"Неверное изображение коллекции");return new Protocol.Frame(theme.id,theme.device,title,path,sha,sha,file.getInt("width"),file.getInt("height"),bytes,at,until);}
    public static JSONObject source(Protocol.Theme theme,String id)throws JSONException {JSONArray rows=theme.descriptor.getJSONArray("sources");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.getString("id").equals(id))continue;Protocol.require(id.equals("real")||id.equals("game-world"),"Неверный источник погоды");String prefix="weather/"+theme.id+"/"+(id.equals("game-world")?"sources/game-world/":"");Protocol.require(Protocol.endpoint(row.getString("current_url"),prefix+"current.json")&&Protocol.endpoint(row.getJSONObject("forecasts").getString(theme.device),prefix+"forecast-"+theme.device+".json"),"Неверный адрес погодного источника");return row;}throw new IllegalArgumentException("Источник погоды недоступен");}
    static String identity(JSONObject object,String key){return object.isNull(key)?"":object.optString(key);}
    public static Protocol.Frame weather(JSONObject current,JSONObject forecast,Protocol.Theme theme,String source,long now)throws JSONException {
        Protocol.require(current.getInt("schema")==1&&current.getString("type").equals("weather")&&current.getString("collection_id").equals(theme.id)&&current.getString("source_id").equals(source),"Неверная текущая погода");
        Protocol.require(forecast.getInt("schema")==1&&forecast.getString("document_type").equals("weather-forecast")&&forecast.getString("collection_id").equals(theme.id)&&forecast.getString("source_id").equals(source)&&forecast.getString("format").equals(theme.device),"Неверный погодный прогноз");
        for(String key:new String[]{"world_id","location_revision","timezone"})Protocol.require(identity(current,key).equals(identity(forecast,key)),"Погодный мир или место изменились: повторю получение");
        ZoneId.of(current.getString("timezone"));Protocol.require(current.has("location_revision")&&forecast.has("location_revision"),"Нет ревизии места");
        Protocol.require(Arrays.asList("ready","not_ready","stale","unresolved_weather").contains(current.optString("status"))&&!forecast.optString("status").equals("unavailable"),"Погодные данные пока недоступны");
        long generated=Protocol.time(forecast.getString("generated_at")),valid=Protocol.time(forecast.getString("valid_until"));Protocol.require(generated<=now&&now<valid,"Прогноз устарел");
        JSONArray rows=forecast.getJSONArray("intervals");Protocol.require(rows.length()<=2000,"Прогноз слишком большой");JSONObject match=null;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);long from=Protocol.time(row.getString("valid_from")),until=Protocol.time(row.getString("valid_until"));Protocol.require(until>from,"Неверный интервал прогноза");if(from<=now&&now<until){Protocol.require(match==null,"Пересекающиеся интервалы прогноза");match=row;}}
        Protocol.require(match!=null&&match.optString("status").equals("ready"),"Текущий погодный кадр ещё не готов");Protocol.require(match.has("state_id")&&match.has("moon_phase"),"Нет состояния погодного кадра");JSONObject f=match.getJSONObject("file");Protocol.require(ImageFormat.fromURL(f.getString("url")).equals(ImageFormat.canonical(f.getString("format")))&&f.getString("rendition").equals(theme.device)&&f.getInt("width")==theme.width&&f.getInt("height")==theme.height,"Неверное погодное изображение");
        Protocol.Frame frame=pictureFrame(f,theme,theme.title+" · "+(source.equals("real")?"Погода Столицы Империи":"Игровой мир"),Protocol.time(match.getString("valid_from")),Math.min(valid,Protocol.time(match.getString("valid_until"))));frame.kind="weather";frame.sourceId=source;
        frame.refreshAt=Math.min(frame.until,Math.min(Protocol.time(current.getString("refresh_after")),Protocol.time(forecast.getString("refresh_after"))));return frame;
    }
    public static String mode(Protocol.Theme theme,String requested){JSONObject schedule=theme.descriptor.optJSONObject("schedule");if(!requested.equals("auto"))return requested;return schedule!=null&&schedule.has("monthly")?"monthly":schedule!=null&&schedule.has("seasonal")?"seasonal":"daily";}
    public static Protocol.Frame ordinary(JSONObject catalogue,Protocol.Theme theme,String requested,long now)throws JSONException {
        String tz=catalogue.optString("timezone","local");ZoneId zone=tz.equals("local")?ZoneId.systemDefault():ZoneId.of(tz);LocalDate date=Instant.ofEpochMilli(now).atZone(zone).toLocalDate();String selected=mode(theme,requested),id=null;long until=date.plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli();
        if(selected.equals("monthly")){id=theme.descriptor.getJSONObject("schedule").getJSONObject("monthly").getString(Integer.toString(date.getMonthValue()));until=date.withDayOfMonth(1).plusMonths(1).atStartOfDay(zone).toInstant().toEpochMilli();}
        else if(selected.equals("seasonal")){String season=date.getMonthValue()>=3&&date.getMonthValue()<=5?"spring":date.getMonthValue()>=6&&date.getMonthValue()<=8?"summer":date.getMonthValue()>=9&&date.getMonthValue()<=11?"autumn":"winter";id=theme.descriptor.getJSONObject("schedule").getJSONObject("seasonal").getString(season);}
        else Protocol.require(selected.equals("daily"),"Неизвестный режим смены");
        JSONArray items=catalogue.getJSONArray("items");List<JSONObject> candidates=new ArrayList<>();for(int i=0;i<items.length();i++){JSONObject row=items.getJSONObject(i);if(row.getString("collection").equals(theme.id)&&(id==null||row.getString("id").equals(id)))candidates.add(row);}Protocol.require(!candidates.isEmpty(),"В коллекции нет текущего изображения");JSONObject item=candidates.get(id==null?(int)Math.floorMod(date.toEpochDay(),(long)candidates.size()):0);
        Protocol.Frame f=pictureFrame(picture(item.getJSONArray("files")),theme,item.getString("title"),date.atStartOfDay(zone).toInstant().toEpochMilli(),until);f.kind="plain";f.sourceId="none";return f;
    }
}
